import Tooltip, { type TooltipProps } from '@mui/material/Tooltip';
import { mergeSlotProps } from '@mui/material/utils';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef } from 'react';

export type SvTooltipProps = TooltipProps;
export const SvTooltip = forwardRef<HTMLElement, SvTooltipProps>(
  function SvTooltip({ className, sx, slotProps, ...props }, ref) {
    return (
      <Tooltip
        {...props}
        ref={ref}
        slotProps={{
          ...slotProps,
          tooltip: mergeSlotProps(slotProps?.tooltip, {
            className: clsx('SvTooltip-root', className),
            sx: mergeSx(
              {
                backgroundColor: 'background.paper',
                color: 'text.primary',
                border: '1px solid',
                borderColor: 'divider',
                borderRadius: '8px',
                p: '8px 12px',
                maxWidth: 280,
                fontSize: 12,
                fontWeight: 400,
                lineHeight: '16px',
                letterSpacing: 0,
                boxShadow: 2,
              },
              sx
            ),
          }),
          arrow: mergeSlotProps(slotProps?.arrow, {
            sx: {
              color: 'background.paper',
              '&::before': { border: '1px solid', borderColor: 'divider' },
            },
          }),
        }}
      />
    );
  }
);
